export function createLogRecord(input, now = () => new Date().toISOString()) {
  return { ...input };
}

import assert from "node:assert/strict";
import { createLogRecord } from "./logger.js";

const record = createLogRecord({
  level: "error",
  environment: "prod",
  requestId: "req-1042",
  route: "POST /orders",
  outcome: "failed",
  durationMs: 842,
  errorName: "DatabaseTimeout",
  authorization: "Bearer secret",
  password: "not-for-logs",
  body: { card: "4111111111111111" },
}, () => "2026-08-11T12:00:00.000Z");

assert.deepEqual(record, {
  timestamp: "2026-08-11T12:00:00.000Z",
  level: "error",
  service: "orders-api",
  environment: "prod",
  requestId: "req-1042",
  route: "POST /orders",
  outcome: "failed",
  durationMs: 842,
  errorName: "DatabaseTimeout",
});
assert.throws(() => createLogRecord({ level: "debug", requestId: "req-1", route: "/" }), /level/);
assert.throws(() => createLogRecord({ level: "info", route: "/" }), /requestId/);
console.log("structured logging contract passed");
